{
  "ledger": {
    "p38:e257": {
      "state": "represented",
      "fact_ids": ["P0038F0001"],
      "note": "적용할 것으로 1번 network_forward(추론) 중간 복사 제거가 제시됨 — 원문 텍스트와 일치"
    },
    "p38:e258": {
      "state": "represented",
      "fact_ids": ["P0038F0015"],
      "note": "바꾸는 과정에 주목할 부분 — 원문에 존재, P0038F0015로 보존됨"
    },
    "p38:e259": {
      "state": "represented",
      "fact_ids": ["P0038F0002", "P0038F0009"],
      "note": "net.act[l] 사용 및 메모리풀 미관리 사실 — P0038F0009가 원문 텍스트를 직접 보존. P0038F0002는 e258과 중복 결합"
    },
    "p38:e260": {
      "state": "represented",
      "fact_ids": ["P0038F0017"],
      "note": "gemini에 따르면 — 출처 귀속만 보존됨 (context_only). 내용 자체는 후속 요소(e261~)에 있음"
    },
    "p38:e261": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "CPU가 net.act[l]의 값(Relu면 0, Sigmoid면 1)을 읽어서 GPU 커널 발사 시 Constant Memory/Registers에 넣어 전달한다는 상세 설명 누락. 원문의 핵심 기술 설명이나 승인된 사실에 전혀 보존되지 않음"
    },
    "p38:e262": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "ActivationType이 단순한 enum(내부적으로 4바이트 정수)이라는 설명 누락"
    },
    "p38:e263": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "enum 값은 cudaMalloc/cudaMemcpy 불필요, 커널 런칭 시 자동 GPU 전달, 속도 저하 없음. 반면 큰 배열/구조체는 포인터로 cudaMemcpy 필요 — 원문의 핵심 구분 설명 전체 누락"
    },
    "p38:e264": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "큰 덩어리는 포인터로, 작은 숫자/Enum은 값으로 전달 가능하다는 요약 누락"
    },
    "p38:e265": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "좀 더 정확히 설명해보자 — 전환 문장 누락. 내용상 e261~e264의 상세 설명으로 이어지는 구조"
    },
    "p38:img0:e0": {
      "state": "represented",
      "fact_ids": ["P0038R0F0006"],
      "note": "코드 주석 '// 3. GPU 내부에서 활성화 함수 적용' 보존됨"
    },
    "p38:img0:e1": {
      "state": "represented",
      "fact_ids": ["P0038R0F0007"],
      "note": "코드 주석 '// 여기서 CPU 메모리에 있는 net.act[1] 를 사용했는데, CUDA 커널 인자 방식을 이해해야함' 보존됨"
    },
    "p38:img0:e2": {
      "state": "represented",
      "fact_ids": ["P0038R0F0008"],
      "note": "커널 발사 코드 apply_activation_gpu<<blocksPerGrid, 256>>>(net.act[1], d_out); 보존됨"
    }
  }
}
